transforms.code:
loadDict = {}
fields = ['clients', 'devices', 'histHrs', 'histSQL', 'histTags', 'tags']
if value is None:
	for field in fields:
		loadDict[field] = 0
else:
	for field in fields: 
		loadDict[field] = value[field] if field in value.keys() else 0
return loadDict

maxSessions = 0
if value["type"] == "standard":
	IAmodules = value["config"]["modules"]["IA"]
	for m in IAmodules:
		if m["name"] in ("Perspective", "Vision"):
			selection = m["selection"]
			if selection == "Unlimited":
				maxSessions += 99999
			else:
				maxSessions += int(selection[:1])
elif value["type"] == "panel":
	maxSessions = 2
elif value["type"] == "edge":
	maxSessions = 0

return min(maxSessions, 99999)

